static int count_one_bits(unsigned long mask) {
  int count = 0;
  while (mask & 1) { count++; mask >>= 1; }
  return count;
}
void convert(unsigned long red_mask) {
  int red_shift = count_trailing_zeroes(red_mask);
  int red_width = count_one_bits(red_mask);
}
